{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C32"],
      "claim": "Linezolid, the closest structural analogue (Morgan 0.4507), has 100% absolute oral bioavailability in humans, directly supporting high F for this oxazolidinone scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "YH4808, a close linezolid-like oxazolidinone analogue (Morgan 0.4054), has low absolute oral bioavailability of 10.1%, showing that certain distal heterocycle modifications can reduce F below 20%.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C06"],
      "claim": "Delpazolid, another oxazolidinone antibiotic, has absolute oral bioavailability of 99.75% in humans, supporting high F for this chemical class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Contezolid, an oxazolidinone antibiotic, has absolute oral bioavailability of 64% in healthy subjects, well above the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The closest and most transferable evidence (linezolid, 100% F) and several other oxazolidinones (delpazolid 99.75%, contezolid 64%) support high oral bioavailability. The only close low-F analogue (YH4808, 10.1%) is less similar and differs in the distal heterocycle and amide substituent, so it does not outweigh the high-F class evidence. Therefore, F >= 20% is better supported.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability measurement for the query molecule.",
    "The specific effects of the morpholin-3-one versus morpholine/thiomorpholine and the chlorothiophene amide on absorption are not directly characterized.",
    "Fasted-state solubility and absorption behavior for this exact analogue are unknown."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

